before.content:
import path from "node:path";

const directory = path.resolve(process.argv[2] ?? path.join(process.cwd(), "build", "stage6-release"));
await mkdir(directory, { recursive: true });
const entries = [];
for (const name of (await readdir(directory)).sort()) {
  const file = path.join(directory, name);
  if (!(await stat(file)).isFile() || name.endsWith(".sig") || name === "release-signing-public.pem"
      || name === "release-signatures.json") continue;
  entries.push({ name, sha256: createHash("sha256").update(await readFile(file)).digest("hex") });
}
if (entries.length === 0) throw new Error("release directory contains no signable artifacts");
const { privateKey, publicKey } = generateKeyPairSync("ed25519");
const publicPem = publicKey.export({ type: "spki", format: "pem" });
await writeFile(path.join(directory, "release-signing-public.pem"), publicPem, { mode: 0o644 });

after.content:
  if (!verify(null, Buffer.from(entry.sha256, "ascii"), publicKey, signature)) {
    throw new Error(`release signature verification failed for ${entry.name}`);
  }
  const signaturePath = path.join(directory, "signatures", `${entry.name}.sig`);
  await mkdir(path.dirname(signaturePath), { recursive: true });
  await writeFile(signaturePath, signature.toString("base64") + "\n", { mode: 0o644 });
}
await writeFile(path.join(directory, "release-signatures.json"), JSON.stringify({
  schemaVersion: 1, algorithm: "Ed25519", publicKey: "release-signing-public.pem", artifactRoot: "artifacts", artifacts: entries,
}, null, 2) + "\n", { mode: 0o644 });
try { await chmod(path.join(directory, "release-signing-public.pem"), 0o644); } catch {}
process.stdout.write(`SIGNED_ARTIFACTS=${entries.length}\nSTAGE6_RELEASE_SIGNATURES_OK\n`);
